import hashlib, subprocess, shutil, os
LEAN = 'def gate (n : Nat) (p q : Nat → Prop) (h : Nat) : Prop :=\n  ∀ g, g < h → g < n ∨ (p g ∧ (q g ∨ ¬ ∀ j, j < g → q j))\ndef blend (S : Nat → Prop) (a b : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ a h) ∨ (¬ S h ∧ b h)\ndef eventual (p : Nat → Prop) : Prop := ∃ H, ∀ h, H ≤ h → p h\ndef dbtrace (n : Nat) (S : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ h = 0) ∨ (¬ S h ∧ h ≤ n)\ndef selfeq (n : Nat) (S d x : Nat → Prop) : Prop :=\n  ∀ h, x h ↔ blend S (fun h => ∀ g, g < h → x g) (gate n x d) h\n\ntheorem first_hole (d : Nat → Prop) (t : Nat)\n    (pre : ∀ j, j < t → d j) (hole : ¬ d t) (g : Nat) :\n    (d g ∨ ¬ ∀ j, j < g → d j) ↔ g ≠ t := by\n  classical\n  constructor\n  · intro H e\n    subst g\n    rcases H with hd | hd\n    · exact hole hd\n    · exact hd pre\n  · intro H\n    by_cases hg : g < t\n    · exact Or.inl (pre g hg)\n    · exact Or.inr (fun hh => hole (hh t (by omega)))\n\ntheorem least_failure (d : Nat → Prop) (b : Nat) (hb : ¬ d b) :\n    ∃ t, t ≤ b ∧ ¬ d t ∧ ∀ j, j < t → d j := by\n  classical\n  induction b using Nat.strongRecOn with\n  | ind b ih =>\n    by_cases H : ∀ j, j < b → d j\n    · exact ⟨b, Nat.le_refl b, hb, H⟩\n    · obtain ⟨j, hj⟩ := Classical.not_forall.mp H\n      have hjb : j < b := Classical.byContradiction (fun hh => hj (fun h => False.elim (hh h)))\n      have hjd : ¬ d j := fun hd => hj (fun _ => hd)\n      obtain ⟨t, ht, hdt, hp⟩ := ih j hjb hjd\n      exact ⟨t, by omega, hdt, hp⟩\n\ndef dd (n : Nat) (S : Nat → Prop) (h : Nat) := ¬ S h ∧ h ≤ n\ndef cd (n : Nat) (S : Nat → Prop) (h : Nat) := S h ∨ h ≤ n\n\ntheorem db_self (n : Nat) (S x : Nat → Prop)\n    (eqn : ∀ h, x h ↔ ¬ S h ∧ gate n x (dd n S) h) :\n    eventual x ↔ (∃ j, S j) ∧ ∀ j, S j → j < n := by\n  classical\n  constructor\n  · intro ⟨H, hH⟩\n    have bound : ∀ j, S j → j < n := by\n      intro j sj\n      by_cases jn : j < n\n      · exact jn\n      · have xz := (eqn (H+j+1)).1 (hH _ (by omega))\n        rcases xz.2 j (by omega) with small | hh\n        · omega\n        · exact False.elim ((eqn j).1 hh.1 |>.1 sj)\n    refine ⟨?_, bound⟩\n    apply Classical.byContradiction\n    intro none\n    have ns : ∀ j, ¬ S j := fun j sj => none ⟨j,sj⟩\n    have pre : ∀ j, j < n+1 → dd n S j := fun j hj => ⟨ns j, by omega⟩\n    have hole : ¬ dd n S (n+1) := by intro hh; have := hh.2; omega\n    have xz := (eqn (H+n+2)).1 (hH _ (by omega))\n    rcases xz.2 (n+1) (by omega) with small | hh\n    · omega\n    · exact (first_hole _ _ pre hole _).1 hh.2 rfl\n  · intro ⟨⟨j,sj⟩, bound⟩\n    have hd : ¬ dd n S j := fun hh => hh.1 sj\n    obtain ⟨t,tj,hole,pre⟩ := least_failure (dd n S) j hd\n    have tn : t < n := by have := bound j sj; omega\n    have allx : ∀ h, n ≤ h → x h := by\n      intro h\n      induction h using Nat.strongRecOn with\n      | ind h ih =>\n        intro hn\n        apply (eqn h).2\n        refine ⟨(fun sh => by have := bound h sh; omega), ?_⟩\n        intro g gh\n        by_cases gn : g < n\n        · exact Or.inl gn\n        · exact Or.inr ⟨ih g gh (by omega), (first_hole _ _ pre hole g).2 (by omega)⟩\n    exact ⟨n, allx⟩\n\ntheorem cb_self (n : Nat) (S x : Nat → Prop)\n    (eqn : ∀ h, x h ↔ S h ∨ (¬ S h ∧ gate n x (cd n S) h)) :\n    eventual x ↔ eventual S := by\n  classical\n  constructor\n  · intro hx\n    by_cases es : eventual S\n    · exact es\n    · have missing : ∃ b, n+1 ≤ b ∧ ¬ S b := by\n        apply Classical.byContradiction\n        intro no\n        apply es\n        refine ⟨n+1, ?_⟩\n        intro b hb\n        exact Classical.byContradiction (fun ns => no ⟨b,hb,ns⟩)\n      obtain ⟨b,hb,ns⟩ := missing\n      have holeb : ¬ cd n S b := by intro hd; rcases hd with hs | hn; exact ns hs; omega\n      obtain ⟨t,tb,hole,pre⟩ := least_failure (cd n S) b holeb\n      have tn : n < t := by\n        apply Classical.byContradiction\n        intro no\n        exact hole (Or.inr (by omega))\n      obtain ⟨H,hH⟩ := hx\n      refine ⟨H+t+1, ?_⟩\n      intro h hh\n      rcases (eqn h).1 (hH h (by omega)) with sh | ⟨_,hw⟩\n      · exact sh\n      · rcases hw t (by omega) with small | rest\n        · omega\n        · exact False.elim ((first_hole _ _ pre hole t).1 rest.2 rfl)\n  · intro ⟨H,hH⟩\n    exact ⟨H, fun h hh => (eqn h).2 (Or.inl (hH h hh))⟩\n\ntheorem traces (n : Nat) (S : Nat → Prop) (h : Nat) :\n    (blend S (fun _ => False) (gate n (fun _ => False) (fun _ => False)) h ↔ dd n S h) ∧\n    (blend S (fun _ => True) (gate n (fun _ => False) (fun _ => False)) h ↔ cd n S h) := by\n  have hw : gate n (fun _ => False) (fun _ => False) h ↔ h ≤ n := by\n    constructor\n    · intro H\n      apply Classical.byContradiction\n      intro hn\n      rcases H n (by omega) with small | rest\n      · omega\n      · exact rest.1\n    · intro hn g gh; exact Or.inl (by omega)\n  unfold blend dd cd\n  rw [hw]\n  simp only [and_false, false_or, and_true]\n  constructor\n  · trivial\n  · constructor\n    · intro hh; rcases hh with sh | hh; exact Or.inl sh; exact Or.inr hh.2\n    · intro hh\n      by_cases sh : S h\n      · exact Or.inl sh\n      · rcases hh with hs | hn; exact False.elim (sh hs); exact Or.inr ⟨sh,hn⟩\n#print axioms db_self\n#print axioms cb_self\n#print axioms traces\n'
assert hashlib.sha256(LEAN.encode()).hexdigest() == 'abe27964c4dfeeacd5847b71dcc1a02b56ddd1678d72b9d11cde7553fb174978'
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'Lean missing'
r = subprocess.run([binary, '--stdin'], input=LEAN, text=True, capture_output=True, timeout=90)
assert r.returncode == 0, r.stdout+r.stderr
assert 'sorryAx' not in r.stdout and r.stdout.count('axioms') == 3
for old,new in [('S j → j < n','S j → j ≤ n'), ('eventual x ↔ eventual S','eventual x ↔ ¬ eventual S'), ('S h ∨ h ≤ n','S h ∨ h < n')]:
    bad=LEAN.replace(old,new)
    assert bad != LEAN
    r=subprocess.run([binary,'--stdin'],input=bad,text=True,capture_output=True,timeout=15)
    assert r.returncode != 0, 'negative control accepted'
print('PASS: three general Lean theorems; three mutations rejected')
